using System.IO;
using System.Linq;
using TabForge.Models;
using TabForge.Services;

namespace TabForge;

// Owns: the importer reading Guitar Pro 5's own files exactly (GP5-saved snapshots from the GP5 differential harness, tools/gp5diff):
// link marks with no partner note yet (hammer-on, slide, tie; TabForge.AlphaTab patch 0004), let ring per note, every beat of an overfull bar, an empty bar as no beats.
// Does not own: the editor, the export.
// Tests: TestGp5OwnFilesImport.
public static partial class SelfTest
{
    // Each fixture is a .gp5 file Guitar Pro 5 itself saved (base64), named by what it holds.
    private const string Gp5OwnHammerOnLast = "";   // bar 1: 15 0 15(hammer-on, nothing after it)
    private const string Gp5OwnSlideLast = "";       // bar 1: 1(legato slide, nothing after it)
    private const string Gp5OwnLetRingChord = "";  // a chord 10 (string 1) + 9 (string 6) where only the 9 rings
    private const string Gp5OwnTieFirst = "";          // a new song: 0(tied) as the very first note
    private const string Gp5OwnOverfull = "";     // bar 2: a half note and nine whole notes in 4/4

    private const string Gp5OwnEmptyBar = "";     // bars 1-3 hold notes, bar 4 is empty (GP5 writes one "empty" beat); a mix table (volume 10) added to that empty beat

    private static SongProject Gp5OwnImport(string base64) => GuitarProImporter.ImportBytes(Convert.FromBase64String(base64), "gp5own.gp5");

    private static IEnumerable<TabNote> Gp5OwnNotes(MeasureModel measure) => measure.Cells.Where(c => !c.IsRest).SelectMany(c => c.Notes);

    private static void TestGp5OwnFilesImport()
    {
        var hammer = Gp5OwnNotes(Gp5OwnImport(Gp5OwnHammerOnLast).Tracks[0].Measures[0]).ToList();
        Check("gp5 own files: a hammer-on on the last note (no next note yet) is kept",
            hammer.Count == 3 && hammer[2].Fret == 15 && hammer[2].Techniques.Contains("HOPO") && !hammer[0].Techniques.Contains("HOPO"),
            string.Join(" ", hammer.Select(n => n.Fret + "[" + string.Join(",", n.Techniques) + "]")));

        var slide = Gp5OwnNotes(Gp5OwnImport(Gp5OwnSlideLast).Tracks[0].Measures[0]).ToList();
        Check("gp5 own files: a legato slide on the last note (no next note yet) is kept",
            slide.Count == 1 && slide[0].Fret == 1 && slide[0].Techniques.Contains("LegatoSlide"),
            string.Join(" ", slide.Select(n => n.Fret + "[" + string.Join(",", n.Techniques) + "]")));

        var ring = Gp5OwnImport(Gp5OwnLetRingChord).Tracks[0].Measures.SelectMany(m => m.Cells)
            .FirstOrDefault(c => c.Notes.Any(n => n.Fret == 10 && n.StringIndex == 0) && c.Notes.Any(n => n.Fret == 9 && n.StringIndex == 5));
        Check("gp5 own files: let ring stays on the chord note that has it, not the whole chord",
            ring is not null && ring.Notes.Single(n => n.Fret == 9).Techniques.Contains("LetRing") && !ring.Notes.Single(n => n.Fret == 10).Techniques.Contains("LetRing"),
            ring is null ? "chord not found" : string.Join(" ", ring.Notes.Select(n => n.Fret + "[" + string.Join(",", n.Techniques) + "]")));

        var tie = Gp5OwnNotes(Gp5OwnImport(Gp5OwnTieFirst).Tracks[0].Measures[0]).ToList();
        Check("gp5 own files: a tie on the first note (nothing before it) is kept, with its fret",
            tie.Count == 1 && tie[0].Fret == 0 && tie[0].Tied,
            string.Join(" ", tie.Select(n => n.Fret + (n.Tied ? "[tie]" : ""))));

        var overfull = Gp5OwnImport(Gp5OwnOverfull).Tracks[0].Measures[1].Cells.Where(c => c.Notes.Count > 0).ToList();
        Check("gp5 own files: every beat of an overfull bar is kept, in order, including the last",
            overfull.Count == 10 && overfull[^1].Notes.Single().Fret == 0 && overfull[^2].Notes.Single().Fret == 2
            && overfull.Zip(overfull.Skip(1)).All(p => (p.First.RhythmicPosition ?? 0) < (p.Second.RhythmicPosition ?? 0)),
            string.Join(" ", overfull.Select(c => string.Join(",", c.Notes.Select(n => n.Fret)) + "@" + c.RhythmicPosition)));
        var empty = Gp5OwnImport(Gp5OwnEmptyBar).Tracks[0].Measures;
        Check("gp5 own files: an empty bar imports with no beats (no rest), so the fill and drawing treat it as empty",
            empty.Count == 4 && empty[3].Cells.All(c => c.Notes.Count == 0 && !c.IsRest) && empty[3].Voice2Cells.All(c => c.Notes.Count == 0 && !c.IsRest)
            && empty.Take(3).All(m => m.Cells.Any(c => c.Notes.Count > 0)),
            string.Join(" | ", empty.Select(m => string.Join(" ", m.Cells.Where(c => c.Notes.Count > 0 || c.IsRest).Select(c => c.IsRest ? "r" : string.Join(",", c.Notes.Select(n => n.Fret)))))));
        Check("gp5 own files: a mix change on an empty bar's empty beat is kept on the bar's first cell",
            empty.Count == 4 && empty[3].Cells.Count > 0 && empty[3].Cells[0].Mix?.Volume == 10,
            empty.Count == 4 ? "mix " + (empty[3].Cells.FirstOrDefault(c => c.Mix is not null)?.Mix?.Volume.ToString() ?? "none") : "bars " + empty.Count);
    }
}